insert into public.challenges (id, title, description, instructions, category, rarity_id, difficulty, points, estimated_minutes, evidence_type, available, tags, created_at) values
  ('c01', 'Quisiera ver qué estás comiendo hoy', 'Tu almuerzo, tu merienda o lo que tengas en el plato ahora mismo.', array['Busca buena luz natural si puedes.', 'Fotografía el plato desde arriba.', 'Bonus: ponle nombre de restaurante elegante.']::text[], 'comida', 'common', 'easy', 10, 2, 'photo', true, array['comida', 'rápido']::text[], '2026-10-29T00:00:00.000Z'),
  ('c02', 'Muéstrame algo que siempre está en tu escritorio', 'Ese objeto que nunca se mueve de su sitio.', array['Elige un objeto fijo de tu mesa de trabajo o estudio.', 'Retira papeles con información personal del encuadre.', 'Fotografíalo en su lugar habitual.']::text[], 'objetos', 'common', 'easy', 10, 2, 'photo', true, array['escritorio']::text[], '2026-10-29T00:00:00.000Z'),
  ('c03', 'Muéstrame tu taza favorita', 'Toda persona tiene una taza que prefiere sobre las demás.', array['Busca tu taza preferida.', 'Piensa por qué es tu favorita.', 'Hazle una foto con estilo.']::text[], 'objetos', 'common', 'easy', 10, 2, 'photo', true, array['cocina']::text[], '2026-10-29T00:00:00.000Z'),
  ('c04', 'Muéstrame el cielo de ahora mismo', 'Nublado, azul o de noche: todos los cielos cuentan.', array['Asómate a una ventana o sal un momento.', 'Encuadra solo el cielo.', 'Observa un minuto antes de volver.']::text[], 'exploracion', 'common', 'easy', 10, 3, 'photo', true, array['exterior', 'calma']::text[], '2026-10-29T00:00:00.000Z'),
  ('c05', 'Muéstrame tu cepillo de dientes', 'Un clásico del día a día. ¿Manual o eléctrico?', array['Busca tu cepillo de dientes.', 'Fotografíalo en su vaso o soporte.']::text[], 'cotidiano', 'common', 'easy', 10, 1, 'photo', true, array['baño', 'rápido']::text[], '2026-10-29T00:00:00.000Z'),
  ('c06', 'Encuentra algo de tu color favorito', 'Demuéstralo con un objeto real.', array['Recorre tu espacio buscando tu color.', 'Elige el objeto que mejor lo represente.', 'Fotografíalo sobre un fondo neutro.']::text[], 'exploracion', 'common', 'easy', 10, 3, 'photo', true, array['color']::text[], '2026-10-29T00:00:00.000Z'),
  ('c07', 'Muéstrame el último libro que hojeaste', 'Libro, cómic, revista o recetario: vale todo.', array['Busca el último que tuviste en las manos.', 'Fotografía la portada.']::text[], 'objetos', 'common', 'easy', 10, 2, 'photo', true, array['lectura']::text[], '2026-10-29T00:00:00.000Z'),
  ('c08', 'Quisiera ver tus zapatos más cómodos', 'Los que eliges cuando el día va a ser largo.', array['Encuentra tu calzado más cómodo.', 'Colócalo en un lugar con buena luz.', 'Fotografíalo.']::text[], 'objetos', 'common', 'easy', 10, 2, 'photo', true, array['ropa']::text[], '2026-10-29T00:00:00.000Z'),
  ('c09', 'Enséñame algo verde cerca de ti', 'Una planta, una hoja o cualquier cosa verde.', array['Busca el verde más cercano.', 'Acércate para captar detalles.']::text[], 'exploracion', 'common', 'easy', 10, 2, 'photo', true, array['naturaleza']::text[], '2026-10-29T00:00:00.000Z'),
  ('c10', 'Bebe un vaso de agua con calma', 'Una pausa pequeña que tu cuerpo agradece.', array['Sírvete un vaso de agua.', 'Bébelo despacio, sin pantallas.', 'Respira hondo al terminar.']::text[], 'bienestar', 'common', 'easy', 10, 2, 'confirmation', true, array['pausa', 'salud']::text[], '2026-10-29T00:00:00.000Z'),
  ('c11', 'Muéstrame algo que siempre llevas contigo', 'Un amuleto, un llavero, un auricular… algo inseparable.', array['Piensa en lo que nunca olvidas al salir.', 'Evita documentos, tarjetas o llaves reconocibles.', 'Fotografía el objeto solo.']::text[], 'objetos', 'common', 'easy', 10, 2, 'photo', true, array['personal']::text[], '2026-10-29T00:00:00.000Z'),
  ('c12', 'Encuentra un objeto perfectamente redondo', 'Platos, botones, monedas, relojes… ¿cuál es el más redondo?', array['Busca tres candidatos redondos.', 'Elige al ganador.', 'Fotografíalo de frente.']::text[], 'exploracion', 'common', 'easy', 10, 3, 'photo', true, array['formas']::text[], '2026-10-29T00:00:00.000Z'),
  ('c13', 'Quisiera ver tu bolígrafo favorito', 'O lápiz, rotulador o lo que uses para escribir.', array['Busca tu herramienta de escritura preferida.', 'Fotografíala junto a un garabato.']::text[], 'objetos', 'common', 'easy', 10, 2, 'photo', true, array['escritura']::text[], '2026-10-29T00:00:00.000Z'),
  ('c14', 'Estírate durante un minuto', 'Cuello, hombros, espalda. Sin prisa.', array['Ponte de pie o siéntate con la espalda recta.', 'Estira suavemente, sin forzar.', 'Respira lento durante todo el minuto.']::text[], 'bienestar', 'common', 'easy', 10, 1, 'confirmation', true, array['movimiento', 'pausa']::text[], '2026-10-29T00:00:00.000Z'),
  ('c15', 'Escribe tres cosas que te hicieron sonreír', 'De esta semana. Pequeñas valen igual.', array['Piensa en los últimos siete días.', 'Escribe tres momentos que te sacaron una sonrisa.']::text[], 'historias', 'common', 'easy', 10, 3, 'text', true, array['gratitud']::text[], '2026-10-29T00:00:00.000Z'),
  ('c16', 'Muéstrame tu snack preferido', 'El que eliges cuando nadie mira.', array['Busca tu snack favorito.', 'Preséntalo como si fuera un anuncio.']::text[], 'comida', 'common', 'easy', 10, 2, 'photo', true, array['comida', 'rápido']::text[], '2026-10-29T00:00:00.000Z'),
  ('c17', 'Encuentra la cosa más pequeña de tu habitación', 'Más pequeña de lo que piensas.', array['Explora cajones y estanterías.', 'Fotografía el objeto junto a tu dedo para dar escala.']::text[], 'exploracion', 'common', 'easy', 10, 4, 'photo', true, array['búsqueda']::text[], '2026-10-29T00:00:00.000Z'),
  ('c18', 'Quisiera ver tu rincón favorito de casa', 'El lugar donde mejor te sientes.', array['Ve a tu rincón preferido.', 'Evita que aparezcan personas o datos de tu dirección.', 'Fotografíalo tal como está.']::text[], 'cotidiano', 'common', 'easy', 10, 2, 'photo', true, array['hogar']::text[], '2026-10-29T00:00:00.000Z'),
  ('c19', 'Haz una sombra divertida con tus manos', 'Un perro, un pájaro o algo que acabas de inventar.', array['Busca una lámpara o luz directa.', 'Crea una figura con las manos sobre una pared.', 'Fotografía la sombra.']::text[], 'creatividad', 'common', 'easy', 10, 3, 'photo', true, array['juego', 'luz']::text[], '2026-10-29T00:00:00.000Z'),
  ('c20', 'Escribe la canción que tienes en la cabeza', 'Esa que no se va desde esta mañana.', array['Escribe el título o un fragmento que recuerdes con tus palabras.']::text[], 'historias', 'common', 'easy', 10, 1, 'text', true, array['música', 'rápido']::text[], '2026-10-29T00:00:00.000Z'),
  ('c21', 'Muéstrame algo que tenga rayas', 'Ropa, tazas, cuadernos… las rayas están por todas partes.', array['Busca un patrón de rayas.', 'Fotografíalo de cerca.']::text[], 'exploracion', 'common', 'easy', 10, 3, 'photo', true, array['patrones']::text[], '2026-10-29T00:00:00.000Z'),
  ('c22', 'Ordena un cajón pequeño', 'Solo uno. Cinco minutos. Gran satisfacción.', array['Elige un cajón pequeño.', 'Saca todo, descarta lo que sobra y vuelve a colocar.', 'Opcional: foto del resultado.']::text[], 'cotidiano', 'common', 'easy', 10, 5, 'photo', true, array['orden']::text[], '2026-10-29T00:00:00.000Z'),
  ('c23', 'Fotografía una textura de muy cerca', 'Madera, tela, piel de una naranja… lo que te llame la atención.', array['Busca una superficie con textura.', 'Acerca la cámara todo lo que pueda enfocar.', '¿Se reconoce qué es?']::text[], 'exploracion', 'common', 'easy', 10, 3, 'photo', true, array['detalle']::text[], '2026-10-29T00:00:00.000Z'),
  ('c24', 'Quisiera ver tu cojín favorito', 'O almohada, manta o peluche. Lo más blandito que tengas.', array['Busca tu objeto más suave.', 'Fotografíalo en su sitio.']::text[], 'cotidiano', 'common', 'easy', 10, 2, 'photo', true, array['hogar']::text[], '2026-10-29T00:00:00.000Z'),
  ('c25', 'Describe tu desayuno ideal en una frase', 'Sin límites de presupuesto ni de calorías.', array['Imagina el desayuno perfecto.', 'Descríbelo en una sola frase.']::text[], 'comida', 'common', 'easy', 10, 2, 'text', true, array['imaginación']::text[], '2026-10-29T00:00:00.000Z'),
  ('c26', 'Respira aire fresco durante cinco minutos', 'Ventana abierta, balcón o paseo corto.', array['Busca un lugar seguro con aire fresco.', 'Deja el móvil a un lado.', 'Respira y observa cinco minutos.']::text[], 'bienestar', 'common', 'easy', 10, 5, 'confirmation', true, array['calma', 'exterior']::text[], '2026-10-29T00:00:00.000Z'),
  ('c27', 'Muéstrame el objeto más colorido que tengas', 'Cuantos más colores, mejor.', array['Busca el objeto con más colores a tu alrededor.', 'Fotografíalo sobre fondo blanco.']::text[], 'objetos', 'common', 'easy', 10, 3, 'photo', true, array['color']::text[], '2026-10-29T00:00:00.000Z'),
  ('c28', 'Encuentra algo que haga un sonido curioso', 'Un juguete, una caja, un vaso con agua…', array['Busca un objeto que suene de forma interesante.', 'Describe el sonido en una frase.']::text[], 'exploracion', 'common', 'easy', 10, 3, 'text', true, array['sonido']::text[], '2026-10-29T00:00:00.000Z'),
  ('c29', 'Escribe una palabra que defina tu día', 'Solo una. Piénsala bien.', array['Repasa tu día hasta ahora.', 'Elige una única palabra.']::text[], 'historias', 'common', 'easy', 10, 1, 'text', true, array['reflexión', 'rápido']::text[], '2026-10-29T00:00:00.000Z'),
  ('c30', 'Quisiera ver tu fruta favorita', 'O verdura. Sin juicios.', array['Busca tu fruta o verdura favorita (o dibújala si no tienes).', 'Fotografíala con buena luz.']::text[], 'comida', 'common', 'easy', 10, 2, 'photo', true, array['comida']::text[], '2026-10-29T00:00:00.000Z'),
  ('q01', 'Encuentra un objeto que tenga más de diez años', 'Algo que ha sobrevivido a una década contigo.', array['Busca un objeto con al menos diez años.', 'Recuerda de dónde salió.', 'Fotografíalo y anota su edad aproximada.']::text[], 'recuerdos', 'curious', 'moderate', 25, 10, 'photo', true, array['nostalgia']::text[], '2026-10-29T00:00:00.000Z'),
  ('q02', 'Fotografía cinco objetos del mismo color', 'Un pequeño bodegón monocromático.', array['Elige un color.', 'Reúne cinco objetos de ese color.', 'Colócalos juntos y fotografía la composición.']::text[], 'creatividad', 'curious', 'moderate', 25, 10, 'photo', true, array['color', 'composición']::text[], '2026-10-29T00:00:00.000Z'),
  ('q03', 'Quisiera ver el objeto más antiguo que conservas', 'El más veterano de tu colección personal.', array['Piensa qué es lo más antiguo que guardas.', 'Fotografíalo con cuidado.', 'Bonus: escribe su historia en una línea.']::text[], 'recuerdos', 'curious', 'moderate', 25, 10, 'photo', true, array['nostalgia', 'historia']::text[], '2026-10-29T00:00:00.000Z'),
  ('q04', 'Dibuja tu comida sin mirar el papel', 'Dibujo a ciegas: el resultado siempre sorprende.', array['Coloca tu comida delante.', 'Dibújala sin mirar el papel ni levantar el lápiz.', 'Fotografía la obra maestra.']::text[], 'creatividad', 'curious', 'moderate', 25, 8, 'photo', true, array['dibujo', 'humor']::text[], '2026-10-29T00:00:00.000Z'),
  ('q05', 'Haz una cara con objetos de la cocina', 'Cucharas como cejas, una taza como nariz…', array['Reúne objetos seguros de cocina (nada de cuchillos).', 'Compón una cara sobre la mesa.', 'Fotografíala desde arriba.']::text[], 'creatividad', 'curious', 'moderate', 25, 10, 'photo', true, array['humor', 'composición']::text[], '2026-10-29T00:00:00.000Z'),
  ('q06', 'Cuenta la historia de un regalo', 'Un objeto que alguien te regaló y que aún conservas.', array['Elige un regalo especial.', 'Escribe cómo llegó a ti, sin datos personales de nadie.']::text[], 'recuerdos', 'curious', 'moderate', 25, 10, 'text', true, array['historia', 'gratitud']::text[], '2026-10-29T00:00:00.000Z'),
  ('q07', 'Ordena diez objetos por tamaño', 'Del más grande al más pequeño, en fila.', array['Reúne diez objetos distintos.', 'Ordénalos por tamaño en línea.', 'Fotografía la fila completa.']::text[], 'creatividad', 'curious', 'moderate', 25, 12, 'photo', true, array['orden', 'composición']::text[], '2026-10-29T00:00:00.000Z'),
  ('q08', 'Encuentra tres cosas que empiecen por M', 'Manzana, mapa, mochila… ¿qué encuentras tú?', array['Explora tu espacio.', 'Reúne tres objetos que empiecen por M.', 'Fotografíalos juntos.']::text[], 'exploracion', 'curious', 'moderate', 25, 8, 'photo', true, array['juego', 'palabras']::text[], '2026-10-29T00:00:00.000Z'),
  ('q09', 'Escribe un haiku sobre tu mañana', 'Tres versos: 5, 7 y 5 sílabas.', array['Piensa en un momento de tu mañana.', 'Escríbelo en tres versos de 5, 7 y 5 sílabas.']::text[], 'historias', 'curious', 'moderate', 25, 10, 'text', true, array['poesía']::text[], '2026-10-29T00:00:00.000Z'),
  ('q10', 'Prepara una bebida como en una cafetería', 'Agua, té o café: la presentación lo es todo.', array['Prepara la bebida que prefieras.', 'Decórala o preséntala con estilo.', 'Fotografíala como para una carta.']::text[], 'comida', 'curious', 'moderate', 25, 10, 'photo', true, array['presentación']::text[], '2026-10-29T00:00:00.000Z'),
  ('q11', 'Fotografía una sombra interesante', 'Las sombras cuentan otra versión de las cosas.', array['Busca una sombra con forma curiosa.', 'Encuádrala sin mostrar el objeto que la proyecta.', '¿Alguien adivinaría qué es?']::text[], 'exploracion', 'curious', 'moderate', 25, 10, 'photo', true, array['luz', 'misterio']::text[], '2026-10-29T00:00:00.000Z'),
  ('q12', 'Muéstrame algo que no usas pero no puedes tirar', 'Todos guardamos algo así.', array['Busca ese objeto inútil pero querido.', 'Fotografíalo.', 'Bonus: ¿por qué lo guardas?']::text[], 'recuerdos', 'curious', 'moderate', 25, 8, 'photo', true, array['nostalgia', 'humor']::text[], '2026-10-29T00:00:00.000Z'),
  ('q13', 'Crea un mini jardín zen', 'Con arena, sal, arroz o lo que tengas a mano.', array['Usa un plato o bandeja como base.', 'Añade un material granulado y algunas piedras u objetos.', 'Traza líneas con un tenedor y fotografía el resultado.']::text[], 'creatividad', 'curious', 'moderate', 25, 15, 'photo', true, array['calma', 'manualidad']::text[], '2026-10-29T00:00:00.000Z'),
  ('q14', 'Aprende a decir «gracias» en un idioma nuevo', 'Uno que nunca hayas estudiado.', array['Elige un idioma desconocido para ti.', 'Aprende cómo se dice «gracias» y cómo se pronuncia.', 'Escríbelo aquí.']::text[], 'exploracion', 'curious', 'moderate', 25, 8, 'text', true, array['idiomas']::text[], '2026-10-29T00:00:00.000Z'),
  ('q15', 'Haz un arcoíris con objetos de tu casa', 'Rojo, naranja, amarillo, verde, azul y violeta.', array['Busca un objeto de cada color.', 'Ordénalos como un arcoíris.', 'Fotografía la composición.']::text[], 'creatividad', 'curious', 'moderate', 25, 15, 'photo', true, array['color', 'composición']::text[], '2026-10-29T00:00:00.000Z'),
  ('d01', 'Recrea una escena de película con objetos domésticos', 'Sin actores: solo objetos, luz e imaginación.', array['Elige una escena icónica de una película.', 'Recréala con objetos de casa.', 'Fotografíala y escribe el título en tu nota mental.']::text[], 'creatividad', 'challenge', 'hard', 50, 30, 'photo', true, array['cine', 'composición']::text[], '2026-10-29T00:00:00.000Z'),
  ('d02', 'Construye una obra de arte con tres objetos cotidianos', 'Una escultura efímera digna de museo.', array['Elige tres objetos que no tengan nada que ver.', 'Combínalos en una escultura estable.', 'Ponle título y fotografíala.']::text[], 'creatividad', 'challenge', 'hard', 50, 20, 'photo', true, array['arte', 'manualidad']::text[], '2026-10-29T00:00:00.000Z'),
  ('d03', 'Cuéntame una historia usando tres objetos', 'Los tres deben ser imprescindibles en la trama.', array['Escoge tres objetos al azar a tu alrededor.', 'Escribe una historia breve donde los tres sean clave.', 'Opcional: título dramático.']::text[], 'historias', 'challenge', 'hard', 50, 20, 'text', true, array['escritura', 'imaginación']::text[], '2026-10-29T00:00:00.000Z'),
  ('d04', 'Recrea una fotografía antigua', 'Una foto tuya, de un lugar o de un objeto, años después.', array['Busca una foto antigua donde salgas tú, un lugar o un objeto.', 'Si aparecen otras personas, consigue su permiso o elige otra.', 'Repite la pose o el encuadre lo más fiel posible.']::text[], 'recuerdos', 'challenge', 'hard', 50, 30, 'photo', true, array['nostalgia', 'fotografía']::text[], '2026-10-29T00:00:00.000Z'),
  ('d05', 'Cocina algo con solo cinco ingredientes', 'Creatividad culinaria con límites.', array['Elige cinco ingredientes que ya tengas (sal y aceite cuentan).', 'Prepara un plato con ellos, con cuidado en la cocina.', 'Emplátalo y fotografíalo.']::text[], 'comida', 'challenge', 'hard', 50, 40, 'photo', true, array['cocina']::text[], '2026-10-29T00:00:00.000Z'),
  ('d06', 'Diseña la portada de un álbum imaginario', 'Inventa el grupo, el título y la portada.', array['Inventa un nombre de grupo y de álbum.', 'Diseña la portada con dibujo, collage u objetos.', 'Fotografía el resultado.']::text[], 'creatividad', 'challenge', 'hard', 50, 30, 'photo', true, array['música', 'diseño']::text[], '2026-10-29T00:00:00.000Z'),
  ('d07', 'Escribe una carta a tu yo de dentro de un año', '¿Qué quieres recordarte?', array['Busca un momento tranquilo.', 'Escribe una carta a tu yo futuro: deseos, preguntas, consejos.', 'Guárdala aquí; es privada.']::text[], 'historias', 'challenge', 'hard', 50, 20, 'text', true, array['reflexión']::text[], '2026-10-29T00:00:00.000Z'),
  ('d08', 'Construye la torre más alta con objetos de cocina', 'Ingeniería doméstica. Nada de vidrio ni objetos cortantes.', array['Usa solo objetos irrompibles: táperes, cucharas de madera, trapos…', 'Construye la torre más alta que se sostenga sola.', 'Fotografíala antes de que caiga.']::text[], 'creatividad', 'challenge', 'hard', 50, 20, 'photo', true, array['juego', 'construcción']::text[], '2026-10-29T00:00:00.000Z'),
  ('d09', 'Haz un paseo fotográfico de diez fotos', 'Elige un tema y búscalo durante tu paseo.', array['Elige un tema: círculos, rojo, sombras…', 'Pasea por un lugar seguro y conocido.', 'Haz diez fotos y comparte aquí tu favorita.']::text[], 'exploracion', 'challenge', 'hard', 50, 40, 'photo', true, array['paseo', 'fotografía']::text[], '2026-10-29T00:00:00.000Z'),
  ('d10', 'Inventa un juego de mesa con lo que tienes', 'Reglas propias, piezas improvisadas.', array['Reúne objetos que sirvan de fichas y tablero.', 'Escribe tres reglas sencillas.', 'Juega una partida y fotografía el tablero.']::text[], 'creatividad', 'challenge', 'hard', 50, 40, 'photo', true, array['juego', 'diseño']::text[], '2026-10-29T00:00:00.000Z'),
  ('l01', 'Crea un museo en miniatura de tu vida', 'Cinco objetos, cinco cartelas, una exposición.', array['Elige cinco objetos que cuenten algo de ti.', 'Escribe una pequeña cartela para cada uno.', 'Monta la exposición y fotografía la sala completa.']::text[], 'recuerdos', 'legendary', 'epic', 100, 60, 'photo', true, array['museo', 'memoria']::text[], '2026-10-29T00:00:00.000Z'),
  ('l02', 'Rueda un cortometraje de 30 segundos sin diálogos', 'Con objetos, sombras o tus manos como protagonistas.', array['Escribe una idea en tres frases: inicio, giro y final.', 'Grábala en 30 segundos sin diálogos.', 'Adjunta un fotograma como recuerdo (el vídeo se queda en tu dispositivo).']::text[], 'creatividad', 'legendary', 'epic', 100, 90, 'photo', true, array['cine', 'vídeo']::text[], '2026-10-29T00:00:00.000Z'),
  ('l03', 'Dibuja un cómic de cuatro viñetas sobre tu día', 'Tu día como si fuera una tira de periódico.', array['Elige cuatro momentos de tu día.', 'Dibuja una viñeta por momento, con bocadillos.', 'Fotografía la tira completa.']::text[], 'creatividad', 'legendary', 'epic', 100, 60, 'photo', true, array['cómic', 'dibujo']::text[], '2026-10-29T00:00:00.000Z'),
  ('l04', 'Dale una segunda vida a un objeto viejo', 'Reinventa algo que ibas a tirar.', array['Elige un objeto en desuso.', 'Transfórmalo para darle un nuevo uso, con herramientas seguras.', 'Fotografía el antes y el después juntos.']::text[], 'creatividad', 'legendary', 'epic', 100, 90, 'photo', true, array['reciclaje', 'manualidad']::text[], '2026-10-29T00:00:00.000Z'),
  ('l05', 'Construye una reacción en cadena casera', 'Fichas, libros, canicas: que una cosa mueva a la siguiente.', array['Diseña un recorrido con al menos cinco pasos.', 'Usa objetos seguros y un espacio despejado.', 'Ponlo en marcha y fotografía el montaje.']::text[], 'creatividad', 'legendary', 'epic', 100, 120, 'photo', true, array['ingeniería', 'juego']::text[], '2026-10-29T00:00:00.000Z')
